+  ['pages/market/MarketPage.tsx', '/market'],
+  ['pages/seller/SellerPage.tsx', '/market/seller'],
+  ['pages/product/ProductPage.tsx', '/market/product/:productSlug'],
+  ['pages/favourites/FavouritesPage.tsx', '/favourites'],
